@php
  $money = static fn ($value) => 'Rs ' . number_format(abs((float) $value), 2);
  $signedMoney = static fn ($value) => ((float) $value < 0 ? '- ' : '') . 'Rs ' . number_format(abs((float) $value), 2);
  $hasFilters = collect(['representative_user_id', 'product_id', 'service_name', 'manager_user_id', 'from_payment_date', 'to_payment_date'])->contains(fn ($key) => request()->filled($key));
  $maxProductProfit = max(1, (float) $productBreakdown->map(fn ($row) => abs($row->profit))->max());
@endphp

