<script>
  $(function(){
    const panel=$('#pnl-filter-card'),button=$('#toggle-pnl-filters'),records=@json($profitLossData->values());let margin='all';
    button.on('click',function(){const open=panel.toggleClass('is-open').hasClass('is-open');button.attr('aria-expanded',open?'true':'false')});
    $('.pnl-export').on('click',function(){const url=new URL('{{ route('admin.report.profit-loss.export') }}',window.location.origin);url.search=new URLSearchParams(window.location.search);url.searchParams.set('format',$(this).data('format'));window.location.href=url.toString()});
    function match(row,q){return [row.customer_name,row.product_name,row.service_name,row.vendor_name,row.sales_person_name,row.manager_name].join(' ').toLowerCase().includes(q)}function refresh(){const q=$('#pnl-search').val().trim().toLowerCase();let count=0;$('[data-pnl-row]').each(function(){const row=records[$(this).data('pnl-row')],show=(margin==='all'||$(this).data('pnl-margin')===margin)&&match(row,q);$(this).toggle(show);if(show&&$(this).is('tr'))count++});$('#pnl-count').text(count+(count===1?' record':' records'))}
    $('.pnl-margin-filter').on('click',function(){margin=$(this).data('pnl-margin');$('.pnl-margin-filter').removeClass('is-active');$(this).addClass('is-active');refresh()});$('#pnl-search').on('input',refresh);
    function esc(value){return $('<div>').text(value||'N/A').html()}function money(value){return 'Rs '+Math.abs(Number(value)).toLocaleString('en-IN',{minimumFractionDigits:2})}
    $('[data-pnl-detail]').on('click',function(){const row=records[$(this).data('pnl-detail')];if(!row)return;const loss=Number(row.profit_loss)<0,profit=(loss?'- ':'')+money(row.profit_loss),detail=(label,value,klass='')=>'<div class="pnl-detail"><label>'+esc(label)+'</label><strong class="'+klass+'">'+esc(value)+'</strong></div>';$('#pnl-detail-title').text(row.customer_name);$('#pnl-detail-content').html('<div class="pnl-detail-grid">'+detail('Customer received',money(row.client_received_amount))+detail('Vendor cost',money(row.vendor_amount))+detail('Gross profit',profit,loss?'pnl-negative':'pnl-positive')+detail('Margin',Number(row.profit_loss_percent).toFixed(2)+'%')+detail('Product',row.product_name)+detail('Service',row.service_name)+detail('Vendor',row.vendor_name)+detail('Paid date',row.paid_date)+detail('Sales person',row.sales_person_name)+detail('Manager',row.manager_name)+'</div>');$('#pnl-detail-modal').addClass('is-open').attr('aria-hidden','false')});
    $('#pnl-close-detail,#pnl-detail-modal').on('click',function(event){if(event.target===this||event.currentTarget.id==='pnl-close-detail')$('#pnl-detail-modal').removeClass('is-open').attr('aria-hidden','true')});$(document).on('keydown',function(event){if(event.key==='Escape')$('#pnl-detail-modal').removeClass('is-open').attr('aria-hidden','true')});
  });
</script>
@endpush
